        {"구절":"나 1:2", "연결점":"여호와는 질투하시며 보복하시는 하나님", "구분":"구약"},
        {"구절":"사 8:7-8", "연결점":"강하고 많은 물 곧 앗시리아 왕이 밀려옴", "구분":"구약"},
        {"구절":"렘 51:42", "연결점":"바다가 바벨론 위에 올라왔도다", "구분":"구약"},
        {"구절":"살후 2:8", "연결점":"주 예수께서 입의 기운으로 불법한 자를 멸하시리라", "구분":"신약"},
        {"구절":"계 19:15", "연결점":"그가 날카로운 칼로 만국을 치시리라", "구분":"신약"},
        {"구절":"계 20:11-15", "연결점":"큰 백색 보좌의 최후 심판", "구분":"신약"},
        {"구절":"계 21:1", "연결점":"바다가 다시 있지 않더라", "구분":"신약"}
