        {"새찬송가":"384", "통일찬송가":"290", "제목":"반석 위에 내가 서리", "선정이유":"변함없는 반석이신 그리스도 위에 세우는 삶"},
        {"새찬송가":"543", "통일찬송가":"371", "제목":"주 예수 넓은 품에", "선정이유":"세상 성벽이 아닌 주님의 품이 참 피난처"},
        {"새찬송가":"339", "통일찬송가":"189", "제목":"주 예수 이름 높이어", "선정이유":"모든 것 위에 높으신 주님의 이름"}
