        {"항목":"칼에 의한 멸망", "내용":"느부갓네살의 바벨론 군대가 본토 두로의 주변 도시들을 먼저 정복했다. 13년간의 포위 전에 주변부부터 함락시키는 전략", "목회적활용":"죄의 결과는 점진적으로 확산된다"},
        {"항목":"여호와를 알게 됨", "내용":"'나를 여호와인 줄 알리라'는 에스겔서의 핵심 주제구. 심판의 궁극적 목적은 파괴가 아니라 하나님을 알게 하는 것", "목회적활용":"모든 역사적 사건 뒤에는 하나님을 알게 하려는 목적이 있다"}
