        {"교리":"연대 심판의 원리", "설명":"두로의 죄가 그 위성 도시들에까지 영향을 미친다. 지도자의 죄가 공동체 전체에 결과를 가져오는 연대 책임의 원리", "관련구절":"수 7:24-25, 삼하 24:15-17, 롬 5:12, 왕상 14:16"},
        {"교리":"하나님 인식의 신학", "설명":"에스겔서에서 70회 이상 등장하는 '인식 공식'은 모든 사건의 궁극적 목적이 하나님을 아는 것임을 선언한다", "관련구절":"사 45:6, 시 46:10, 합 2:14, 빌 2:10-11"}
