        {"교리":"불가피한 심판", "설명":"공성 장비가 하나씩 준비되는 과정은 심판의 불가피함을 보여준다. 한 번 선포된 심판은 체계적으로 집행된다", "관련구절":"나 1:9, 암 9:1-4, 렘 11:11, 사 24:17-18"},
        {"교리":"심판의 도구와 하나님의 주권", "설명":"바벨론의 군사 기술이 심판의 도구로 사용되지만, 그 배후의 주체는 하나님이시다", "관련구절":"사 10:15, 렘 51:20, 시 17:13-14, 사 37:26"}
