        {"대지":"2대지: 성읍이 무너진 것처럼 (저항의 무용)", "내용":"이미 무너진 성에 들어가듯 저항 없이 진입한다. 하나님이 결정하시면 인간의 저항은 무용하다", "예화_적용":"하나님의 뜻 앞에서 교만하게 버티는 것은 태풍 앞에서 우산을 펴는 것과 같다"},
        {"대지":"3대지: 성문으로 들어옴 (최종 함락)", "내용":"기병이 성문으로 들어오는 것은 도시의 최종 함락을 의미한다. 도망칠 곳이 없는 완전한 심판", "예화_적용":"그러나 예수 그리스도 안에는 피난처가 있다. 심판의 문이 아닌 구원의 문이 열려 있다"},
        {"대지":"결론", "내용":"두로의 함락은 인간 교만의 최후를 보여준다. 그러나 우리에게는 아직 기회가 있다. 심판의 날이 오기 전에 은혜의 문으로 들어가자", "예화_적용":"예수님은 '내가 문이니 나로 말미암아 들어가면 구원을 받으리라'고 하셨다"}
