        {"영어원문":"Thy stones, timber, and dust they shall lay in the midst of the water; this was literally fulfilled by Alexander.", "한국어번역":"네 돌과 나무와 흙을 물 가운데에 던질 것이니, 이것은 알렉산더에 의해 문자 그대로 성취되었다.", "핵심통찰":"예언의 문자적 성취는 하나님 말씀의 정확성을 증명한다"},
        {"영어원문":"The pleasant houses, the houses of their delight, shall be destroyed; those who make the world their paradise shall lose it.", "한국어번역":"화려한 집들 곧 그들이 기뻐하던 집들이 파괴될 것이니, 세상을 낙원으로 삼는 자들은 그것을 잃으리라.", "핵심통찰":"세상의 화려함을 낙원으로 삼으면 결국 잃게 된다"}
