        {"대지":"3대지: 두려움을 입음 (새로운 옷)", "내용":"화려한 옷 대신 두려움을 입는다. 교만의 옷 대신 공포의 옷을 입게 되는 역전", "예화_적용":"그러나 그리스도 안에서는 두려움 대신 구원의 옷을 입을 수 있다 (사 61:10)"},
        {"대지":"결론", "내용":"세상의 왕들이 보좌에서 내려와 땅에 앉듯, 우리도 하나님 앞에 겸손해져야 한다. 스스로 낮아지는 자가 높아지고, 스스로 높이는 자가 낮아진다", "예화_적용":"왕의 보좌가 아닌 하나님의 보좌 앞에 무릎 꿇는 자가 진정한 승리자이다"}
