        {"항목":"두려움을 일으킴", "내용":"두로는 강력한 해군력으로 지중해에서 두려움의 대상이었다. 그러나 이제 그 두려움의 주체가 멸망의 대상이 되었다", "목회적활용":"다른 이를 두렵게 한 자가 결국 자신이 두려움의 대상이 된다"}
