        {"원어":"אֶרֶץ תַּחְתִּיּוֹת (에레츠 타흐티요트)", "의미_문법":"가장 낮은 땅/지하 세계 - 명사구. 스올의 깊은 곳", "설교포인트":"가장 높았던 자가 가장 낮은 곳으로 내려간다"},
        {"원어":"יוֹרְדֵי בוֹר (요르데이 보르)", "의미_문법":"구덩이에 내려가는 자들 - 분사+명사. 죽어가는 자들", "설교포인트":"교만한 자는 결국 죽음의 동반자가 된다"}
