        {"교리":"영원한 심판의 확정", "설명":"'영원히'라는 표현은 이 심판이 시간의 제한 없이 영구적임을 선언한다", "관련구절":"계 14:11, 마 25:46, 단 12:2, 유 1:13"},
        {"교리":"하나님 말씀의 최종 권위", "설명":"'주 여호와의 말씀이니라'로 26장 전체 예언이 확정된다. 하나님의 말씀에 대한 항소는 없다", "관련구절":"사 40:8, 벧전 1:25, 시 119:89, 마 24:35"}
