        {"영어원문":"She said, I am of perfect beauty; this was her glorying, and this was her sin, for it was God that made her beautiful.", "한국어번역":"두로가 '나는 온전히 아름답다'고 한 것이 자랑이자 죄였으니, 아름답게 만드신 분은 하나님이셨기 때문이다.", "핵심통찰":"하나님이 주신 것을 자기 것으로 자랑하는 것이 죄이다"},
        {"영어원문":"Those whom God has blessed with advantages of situation and trade ought to give Him the glory of them, not themselves.", "한국어번역":"하나님이 위치와 무역의 이점으로 축복하신 자들은 그 영광을 자기에게가 아니라 하나님께 돌려야 한다.", "핵심통찰":"모든 축복에 대한 영광은 하나님께 돌려야 한다"}
