        {"대지":"2대지: 여러 섬 백성과 거래하는 자 (축복의 열매)", "내용":"국제 무역의 중심이 된 것은 하나님의 축복이었다. 문제는 축복을 누리면서 축복의 주인을 잊은 것이다", "예화_적용":"성공한 사업가가 초심을 잃고 교만해지듯, 축복이 많을수록 감사를 잊기 쉽다"},
        {"대지":"3대지: 나는 온전히 아름답다 (교만의 선언)", "내용":"자기를 '완전하다' 선언하는 것은 하나님의 자리를 차지하는 것이다. 완전하신 분은 오직 하나님뿐이시다", "예화_적용":"잠언 16:18 '교만은 패망의 선봉이요'. 역사상 모든 제국은 자만할 때 무너졌다"},
        {"대지":"결론", "내용":"두로의 비극은 하나님의 축복을 자기 자랑으로 바꾼 것이었다. 우리도 받은 은혜를 잊고 자기 능력을 자랑할 때 같은 위험에 빠진다. 모든 아름다움의 원천이신 하나님께 영광을 돌리자", "예화_적용":"오늘 내가 가진 모든 것이 하나님의 은혜임을 고백하자"}
