        {"대지":"서론", "내용":"두로가 바다 한가운데 서 있다. 건설자들이 아름다움을 온전케 했다. 마치 거대한 배처럼 바다 위에 떠 있는 이 도시는 고대 세계의 경이였다. 그러나 이 장엄한 배는 침몰을 향해 항해하고 있었다", "예화_적용":"타이타닉호의 출항처럼, 가장 화려한 시작이 가장 비극적인 결말을 맞이할 수 있다"},
        {"대지":"1대지: 바다 가운데에 있음이여 (전략적 위치)", "내용":"바다 한복판이라는 천혜의 위치는 하나님이 허락하신 것이다. 두로의 번영의 기초는 하나님의 섭리적 배치였다", "예화_적용":"내가 태어난 시대, 나라, 가정은 내가 선택한 것이 아니라 하나님이 정하신 것이다"},
        {"대지":"2대지: 건설한 자가 온전케 하였도다 (인간의 업적)", "내용":"두로의 건축가들이 이룬 놀라운 성취를 하나님도 인정하신다. 그러나 인간의 업적은 영원하지 않다", "예화_적용":"바벨탑을 쌓으려 한 인간의 노력처럼, 하나님 없는 건설은 결국 무너진다"},
        {"대지":"3대지: 배의 비유가 시작된다 (침몰의 예고)", "내용":"두로를 배에 비유하는 것 자체가 불길한 예고이다. 배는 침몰할 수 있기 때문이다. 아무리 견고한 배도 폭풍 앞에서는 무력하다", "예화_적용":"인생은 항해와 같다. 좋은 배가 아니라 좋은 선장이 중요하다. 그 선장은 그리스도이시다"},
        {"대지":"결론", "내용":"두로의 아름다움은 실재했다. 그러나 그것이 영원하지 않았다. 인간의 업적도 마찬가지이다. 영원한 것은 오직 하나님의 나라뿐이다. 우리의 인생이라는 배를 그리스도께 맡기자", "예화_적용":"나의 인생 항해를 그리스도라는 선장께 맡기는 것이 가장 안전한 선택이다"}
