        {"상황":"하나님이 주신 재능을 세속적으로만 사용하는 분", "성경원리":"성전에 쓰일 백향목이 두로의 돛대가 되었듯, 하나님의 선물이 세속적 목적으로 전용될 수 있다", "실제적용":"하나님이 주신 재능의 첫 열매를 하나님께 드리라. 재능의 참된 목적은 하나님 영광이다"}
