        {"대지":"2대지: 오목 - 희귀함의 유혹", "내용":"오목은 극히 희귀한 목재이다. 희귀한 것을 소유하려는 인간의 욕구는 끝이 없다", "예화_적용":"한정판을 사기 위해 밤새 줄을 서는 현대인처럼, 희귀한 것에 대한 집착은 오래된 인간의 욕심이다"},
        {"대지":"3대지: 여러 섬이 네 시장이 됨 - 경제적 종속", "내용":"여러 섬이 두로의 시장에 종속된 것은 경제적 불평등 구조를 보여준다. 원자재를 제공하는 약소국과 완제품을 판매하는 강대국의 불균형", "예화_적용":"글로벌 무역에서의 불균형은 고대부터 있었다. 공정한 거래가 하나님의 뜻이다"},
        {"대지":"결론", "내용":"두로의 시장에는 상아와 오목이 넘쳤지만, 이 사치품이 심판의 날에 두로를 구하지 못했다. 참으로 값진 것은 희귀한 물건이 아니라 하나님과의 관계이다", "예화_적용":"시편 27:4 '내가 여호와께 바라는 한 가지 일이여 그것을 구하리니 여호와의 아름다움을 앙망하는 것이라'"}
