        {"영어원문":"How busy these tradesmen were! But while they were saying Peace and safety, sudden destruction came upon them.", "한국어번역":"이 상인들이 얼마나 분주했던가! 그러나 평안하다 안전하다 말하는 동안 갑작스러운 멸망이 그들에게 임했다.", "핵심통찰":"분주한 상업 활동 중에 갑작스러운 심판이 임한다"},
        {"영어원문":"The variety of Tyre's trade shows the insatiable desire of gain which nothing can satisfy but the grace of God.", "한국어번역":"두로의 다양한 무역은 하나님의 은혜 외에는 아무것도 만족시킬 수 없는 끝없는 이익 욕구를 보여준다.", "핵심통찰":"오직 하나님의 은혜만이 끝없는 욕구를 채울 수 있다"}
