        {"대지":"서론", "내용":"아람이 두로에 가져온 무역 품목 목록이 화려하다. 남보석, 자색 천, 수놓은 것, 가는 베, 산호, 홍보석. 보석 가게, 직물 시장, 보석 세공소가 한데 모인 것 같다. 두로는 고대 세계의 명품 백화점이었다", "예화_적용":"전 세계 명품을 한 곳에 모은 듯한 두로의 시장, 그러나 이 화려함은 영원하지 않았다"},
        {"대지":"1대지: 남보석과 홍보석 (대제사장 흉패의 보석)", "내용":"대제사장의 흉패에 사용된 보석이 상업적으로 거래된다. 거룩한 것이 세속 시장에 나온 것이다", "예화_적용":"교회의 성물이 골동품 가게에서 팔리는 것처럼, 거룩한 것이 세속화될 때 슬픔이 있다"},
        {"대지":"2대지: 자색 천과 가는 베 (성막 재료의 상업화)", "내용":"성막에 사용된 재료가 일반 무역 품목이 되었다. 거룩함의 상업화는 영적 타락의 증거이다", "예화_적용":"돈으로 거룩함을 사려 한 시몬(행 8:18-20)처럼, 영적 가치의 상업화는 경계해야 한다"},
        {"대지":"3대지: 산호 - 바다 깊은 곳까지 (탐욕의 깊이)", "내용":"산호는 바다 깊은 곳에서 채취한다. 땅의 보석으로 만족하지 못하고 바다 깊은 곳까지 뒤지는 탐욕", "예화_적용":"깊은 바다, 높은 산, 먼 우주까지 자원을 탐하는 인간의 탐욕에는 끝이 없다"},
        {"대지":"결론", "내용":"두로의 시장에는 보석과 직물과 산호가 넘쳤다. 그러나 이 모든 것이 심판의 날에 무용했다. 참된 보화는 그리스도 안에 있다(골 2:3). 세상의 보석보다 값진 하나님의 은혜를 추구하자", "예화_적용":"잠언 3:15 '지혜는 진주보다 귀하니 네가 사모하는 모든 것이 이에 비교할 수 없다'"}
