    표5_매튜헨리: [
        {"영어원문":"Dedan traded with Tyre in precious clothes for chariots, or saddle-cloths for riding, showing the extent of Tyre's commerce.", "한국어번역":"드단이 수레용 또는 승마용 귀한 천으로 두로와 교역했으니, 두로 상업의 범위를 보여준다.", "핵심통찰":"사소한 물품까지도 두로의 무역 네트워크에 포함되었다"},
        {"영어원문":"Even the products of the desert were brought to Tyre's market; nothing was too remote or too humble for her trade.", "한국어번역":"사막의 산물까지 두로의 시장에 가져왔으니, 너무 먼 것도 너무 비천한 것도 두로의 무역에서 제외되지 않았다.", "핵심통찰":"탐욕은 먼 것이든 비천한 것이든 가리지 않는다"},
        {"영어원문":"The variety and extent of Tyre's trade are set forth to show what a great loss the world would sustain by her fall.", "한국어번역":"두로 무역의 다양성과 범위를 제시한 것은 두로의 몰락으로 세계가 얼마나 큰 손실을 입을지를 보여주기 위함이다.", "핵심통찰":"한 도시의 몰락이 전 세계에 충격을 줄 정도의 영향력"}
    ],
    표6_설교자료: [
        {"대지":"제목", "내용":"안장 천의 무역 - 일상까지 장악한 상업 제국", "예화_적용":"두로의 무역은 사치품뿐 아니라 일상 용품까지 장악했다"},
        {"대지":"서론", "내용":"드단이 안장 천을 가지고 두로와 거래했다. 보석이나 금은이 아닌 안장 천이라는 일상적 물품이다. 두로의 무역은 사치품만이 아니라 생활의 모든 영역에 걸쳐 있었다. 이것은 두로가 단순한 무역 도시가 아니라 세계 경제의 중심이었음을 보여준다", "예화_적용":"아마존이 책만 팔다가 이제 생활 전체를 장악하듯, 두로도 모든 일상을 장악했다"},
        {"대지":"1대지: 드단의 안장 천 (사막의 특산물)", "내용":"사막 유목민의 특산물인 안장 천까지 두로의 시장에 도달했다. 어떤 곳도 두로의 상업 네트워크에서 벗어나지 못했다", "예화_적용":"오지 마을까지 배달되는 택배처럼, 두로의 무역 네트워크는 빈틈이 없었다"},
        {"대지":"2대지: 일상의 거래화 (시장 만능주의)", "내용":"안장 천이라는 일상적 물품까지 거래 대상이 된 것은 모든 것을 사고파는 시장 만능주의를 보여준다", "예화_적용":"시간, 관계, 건강까지 돈으로 환산하는 현대 사회. 돈으로 살 수 없는 것이 진정 가치 있는 것이다"},
        {"대지":"3대지: 이동의 수단 (어디로 가는가)", "내용":"안장 천은 이동을 위한 것이다. 중요한 것은 무엇을 타느냐가 아니라 어디로 가느냐이다", "예화_적용":"좋은 차를 가졌지만 방향이 틀리면 목적지에 도달할 수 없듯, 인생의 방향이 중요하다"},
        {"대지":"결론", "내용":"안장 천 하나에도 세계 경제의 흐름이 담겨 있다. 그러나 이 모든 무역과 경제도 하나님의 주권 아래 있다. 일상의 작은 것에서도 하나님의 주권을 인정하는 것이 참된 신앙이다", "예화_적용":"고전 10:31 '먹든지 마시든지 무엇을 하든지 다 하나님의 영광을 위하여 하라'"}
    ],
