        {"구절":"엡 3:6", "연결점":"이방인들이 복음으로 말미암아 함께 상속자가 되고", "구분":"신약"},
        {"구절":"벧전 1:19", "연결점":"흠 없고 점 없는 어린 양 같은 그리스도의 보배로운 피", "구분":"신약"}
