        {"새찬송가":"305", "통일찬송가":"251", "제목":"나 같은 죄인 살리신", "선정이유":"보석보다 귀한 구원의 은혜"},
        {"새찬송가":"289", "통일찬송가":"99", "제목":"만 입이 내게 있으면", "선정이유":"금과 향료보다 귀한 찬양을 드림"}
