        {"대지":"2대지: 영화로웠도다 (영광의 무거움)", "내용":"'카바드'는 영광과 무거움의 이중 의미를 가진다. 두로의 영광이 곧 침몰의 무게가 된다", "예화_적용":"타이타닉호가 '침몰 불가능'이라 불린 것이 교만이었듯, 영광에 취하면 위험을 보지 못한다"},
        {"대지":"3대지: 바다 한가운데에서 (고립된 번영)", "내용":"바다 한가운데라는 위치는 영광이자 고립이다. 풍성해도 외로운 것, 이것이 하나님 없는 번영의 본질이다", "예화_적용":"도시 한가운데 홀로 있는 부자의 고독처럼, 물질이 관계를 대체하지 못한다"},
        {"대지":"결론", "내용":"'풍성하고 영화로웠도다' - 이것이 두로에 대한 마지막 찬사이다. 다음 절부터는 폭풍과 침몰이 시작된다. 절정에서 교만하지 않고, 풍성함에서 감사할 줄 아는 것이 지혜이다. 참된 영광은 하나님의 영광이며, 참된 풍성함은 그리스도 안의 충만함이다", "예화_적용":"에베소서 3:19 '그리스도의 사랑을 알아 하나님의 모든 충만하심으로 충만하게 되기를 구하노라'"}
