        {"대지":"제목", "내용":"동풍이 불다 - 심판의 바람", "예화_적용":"하나님의 심판은 바람처럼 갑작스럽고 거부할 수 없다"},
        {"대지":"서론", "내용":"장면이 급변한다. 25절까지 풍성하고 영화롭던 두로의 배에 동풍이 분다. 사막에서 불어오는 뜨겁고 파괴적인 바람. 사공들이 아무리 노를 저어도 소용없다. 바다 한가운데에서 배가 산산이 부서진다. 영광의 절정이 한순간에 파멸로 바뀌었다", "예화_적용":"2008년 리먼 브라더스 파산처럼, 금융 제국이 하루아침에 무너질 수 있다"},
        {"대지":"1대지: 사공이 큰 물 위로 저어갔거늘 (인간의 노력)", "내용":"사공들은 최선을 다해 노를 저었다. 그러나 인간의 노력이 하나님의 뜻을 거스를 수 없었다", "예화_적용":"아무리 열심히 일해도 하나님의 뜻에 반하면 결국 좌절한다. 방향이 먼저이고 노력은 그 다음이다"},
        {"대지":"2대지: 동풍이 너를 깨뜨렸도다 (하나님의 심판)", "내용":"동풍은 하나님의 심판의 상징이다. 홍해를 가르신 동풍(출 14:21)이 이제 두로를 깨뜨린다. 같은 바람이 구원도 되고 심판도 된다", "예화_적용":"같은 태양이 밀랍을 녹이고 진흙을 굳히듯, 같은 하나님의 임재가 순종하는 자에게는 구원이, 불순종하는 자에게는 심판이 된다"},
        {"대지":"3대지: 바다 한가운데에서 (영광의 자리가 심판의 자리로)", "내용":"4절에서 영광의 자리였던 '바다 한가운데'가 심판의 자리가 되었다. 축복의 장소에서 불순종하면 그곳이 심판의 장소가 된다", "예화_적용":"교회가 영광의 장소이지만, 그 안에서 교만하면 심판의 장소가 될 수 있다"},
        {"대지":"결론", "내용":"동풍이 불었다. 순식간에 모든 것이 변했다. 풍성함이 공허로, 영광이 수치로 바뀌었다. 이 동풍 앞에서 살아남는 유일한 방법은 하나님 앞에 겸손히 순종하는 것뿐이다. 바람도 바다도 순종하는 분(막 4:41)께 우리의 인생을 맡기자", "예화_적용":"마가복음 4:41 '바람과 바다도 순종하는 이가 누구이뇨'"}
