        {"영어원문":"They shall make themselves bald and gird themselves with sackcloth; the marks of the deepest mourning for Tyre.", "한국어번역":"그들이 머리를 밀고 굵은 베를 입을 것이니, 두로를 위한 가장 깊은 애도의 표시이다.", "핵심통찰":"가장 깊은 애도가 두로의 멸망 앞에서 표현된다"},
        {"영어원문":"Instead of the rich garments they wore in Tyre's service, they now wear sackcloth in Tyre's funeral.", "한국어번역":"두로를 섬길 때 입던 화려한 옷 대신, 이제 두로의 장례에 굵은 베를 입는다.", "핵심통찰":"화려한 옷이 장례복으로 바뀌는 것이 세상 영광의 결말"},
        {"영어원문":"Bitterness of soul is the worst of all bitterness; it is the soul that feels the smart of Tyre's fall.", "한국어번역":"영혼의 쓰라림이 모든 쓰라림 중 가장 심한 것이니, 두로의 몰락의 고통을 느끼는 것은 영혼이다.", "핵심통찰":"가장 깊은 고통은 영혼의 고통이다"}
