        {"원어":"מִי (미)", "의미_문법":"누가/어디 - 의문 대명사. 수사적 질문", "설교포인트":"비교할 수 없는 두로의 독보적 위치를 표현"},
        {"원어":"כְּצוֹר (케초르)", "의미_문법":"두로 같은 - 전치사+고유명사. 비교 불가의 수사", "설교포인트":"한때 비교 불가였던 도시의 멸망이 더욱 충격적"},
        {"원어":"כְּדֻמָּה (케두마)", "의미_문법":"적막한/침묵하는 - 전치사+명사. 완전한 고요", "설교포인트":"번잡하던 시장이 죽음의 적막으로 변했다"}
