    표2_역사적배경: [
        {"항목":"두로의 경제적 영향력", "내용":"두로가 '여러 백성을 풍족하게 하고 세상의 왕들을 부유하게 했다'는 것은 과장이 아니다. 고대 지중해 세계의 무역은 대부분 두로를 통해 이루어졌으며, 각국의 왕실이 두로의 무역에 의존했다", "목회적활용":"경제적 영향력이 커질수록 그 상실의 충격도 커진다"},
        {"항목":"과거 회상의 수사법", "내용":"33절은 두로의 과거 영화를 회상하는 부분이다. 현재의 멸망과 과거의 영광을 대비시킴으로써 상실의 크기를 극대화하는 애가의 전형적 수사법이다(애 1:1 참조)", "목회적활용":"과거의 영광이 클수록 현재의 상실이 더 아프게 느껴진다"},
        {"항목":"세상의 왕들의 의존", "내용":"두로의 무역으로 부유해진 왕들은 솔로몬(왕상 10장), 이집트 파라오, 바벨론 왕 등 당대의 강대국 통치자들이었다. 이들이 두로에 경제적으로 의존했다는 것은 두로의 실질적 영향력이 정치적 패권을 초월했음을 보여준다", "목회적활용":"경제적 영향력이 정치적 권력보다 실질적으로 더 강할 수 있다"}
    ],
    표3_신학적의미: [
        {"교리":"축복의 도구에서 심판의 대상으로", "설명":"두로가 여러 백성을 풍족하게 한 것은 일종의 축복의 도구 역할이었다. 그러나 이 역할을 자기 영광으로 돌렸기에 심판의 대상이 되었다. 축복의 도구는 축복의 원천(하나님)을 가리켜야 한다", "관련구절":"창 12:2-3, 신 8:17-18, 호 2:8, 사 10:15"},
        {"교리":"과거의 영광과 현재의 심판", "설명":"과거에 '풍족하게 했다(히스비아)'는 완료형이 현재의 멸망과 대비된다. 과거의 선행이 현재의 교만을 면죄하지 못한다. 하나님은 현재의 마음을 보신다", "관련구절":"겔 18:24, 겔 33:13, 마 7:22-23, 계 2:4-5"},
        {"교리":"세상 왕들에 대한 영향력", "설명":"두로가 세상의 왕들을 부유하게 했다는 것은 경제적 영향력이 정치적 권력을 초월함을 보여준다. 그러나 하나님의 주권은 경제와 정치 모두를 초월한다", "관련구절":"잠 21:1, 단 2:21, 시 2:1-4, 계 17:14"}
    ],
