        {"대지":"3대지: 하나님께 대하여 부유하지 못함 (결정적 결함)", "내용":"세상을 부유하게 해도 하나님 앞에서 가난하면 아무 소용이 없다(눅 12:21)", "예화_적용":"세계 최고 부호도 하나님 앞에 빈손이면 가장 가난한 자이다. 참된 부요는 하나님과의 관계에 있다"},
        {"대지":"결론", "내용":"두로는 세상을 풍족하게 했지만 하나님 앞에서는 빈곤했다. 누가복음 12:21의 '자기를 위하여 재물을 쌓아두고 하나님께 대하여 부요하지 못한 자'가 바로 두로이다. 우리는 어떠한가? 세상에서는 성공했지만 하나님 앞에서는 빈곤하지 않은가", "예화_적용":"눅 12:21 '하나님께 대하여 부요하지 못한 자가 이와 같으리라'"}
