        {"상황":"권력을 가진 지도자의 교만", "성경원리":"두로 왕은 성공과 안전이라는 토대 위에서 자기를 신격화했다. 권력은 교만의 가장 위험한 토양이다", "실제적용":"권력이 클수록 더 겸손해야 한다. 모든 권력은 하나님으로부터 온 것이다(롬 13:1). 청지기 의식을 가지라"},
        {"상황":"하나님 없이도 잘 살 수 있다고 생각하는 분", "성경원리":"두로 왕은 '나는 신이라'며 자급자족을 선언했으나, 그것이 멸망의 원인이 되었다", "실제적용":"스스로 충분하다는 생각이 가장 위험한 착각이다. 요 15:5 '나를 떠나서는 너희가 아무것도 할 수 없느니라'"}
