    표8_상담적용: [
        {"상황":"자랑하던 것을 잃은 분", "성경원리":"두로 왕은 자랑하던 '지혜의 아름다움'이 파괴당했다. 자랑한 것으로 심판받는 것이 하나님의 방식이다", "실제적용":"잃어버린 것이 있다면, 그것에 교만을 붙이지 않았는지 돌아보라. 상실이 겸손의 기회가 될 수 있다"},
        {"상황":"강한 적을 만나 두려운 분", "성경원리":"바벨론이라는 강대국도 하나님의 도구에 불과했다. 적의 행동도 하나님의 주권 안에 있다", "실제적용":"적이 강해 보여도 하나님은 더 강하시다. 시 46:1 '하나님은 우리의 피난처요 힘이시니 환난 중에 만날 큰 도움이시라'"},
        {"상황":"성공이 무너지는 것을 경험하는 분", "성경원리":"두로의 영화가 더럽혀진 것처럼, 세상의 성공은 영원하지 않다", "실제적용":"성공의 무너짐이 영원한 무너짐은 아니다. 하나님 안에서 새로운 기초를 놓을 수 있다. 고전 3:11 '이미 놓인 터 곧 예수 그리스도 외에 다른 터를 놓을 자가 없다'"}
    ],
