        {"구절":"눅 14:11", "연결점":"자기를 높이는 자는 낮아지고 낮추는 자는 높아지리라", "구분":"신약"},
        {"구절":"히 12:2", "연결점":"십자가를 참으사 부끄러움을 개의치 아니하신 그리스도", "구분":"신약"},
        {"구절":"눅 21:20-24", "연결점":"예루살렘이 군대에게 에워싸이는 것을 보거든 - 하나님의 심판 도구", "구분":"신약"}
