        {"구절":"고후 11:14", "연결점":"사탄도 자기를 광명의 천사로 가장한다", "구분":"신약"},
        {"구절":"눅 23:43", "연결점":"오늘 네가 나와 함께 낙원에 있으리라 - 잃어버린 에덴의 회복", "구분":"신약"}
