        {"상황":"하나님께 가까이 있으면서도 교만해진 분", "성경원리":"화광석 사이에서 왕래하던 존재도 교만으로 타락했다. 하나님께 가까이 있는 것이 자동으로 겸손을 보장하지 않는다", "실제적용":"하나님께 가까이 갈수록 자기를 더 낮추라. 사 6:5의 이사야처럼 하나님의 거룩함 앞에서 자기의 부족함을 깨닫는 것이 참된 영성이다"}
