        {"구분":"창조된 날로부터 완전", "내용":"하나님이 만드신 대로 완전했던 존재", "그리스도연결":"그리스도는 태초부터 영원까지 완전하심 (히 13:8, 계 1:8)"},
        {"구분":"불의가 드러남", "내용":"숨겨져 있던 악이 밖으로 나타남", "그리스도연결":"그리스도는 모든 것을 빛 가운데 드러내심 (요 3:20-21, 엡 5:13)"}
