        {"상황":"한때 신앙이 좋았으나 지금은 타락한 분", "성경원리":"'완전하더니 마침내 불의가 드러났다' - 신앙의 타락은 점진적으로 올 수 있다", "실제적용":"타락은 갑자기 오지 않고 서서히 온다. 지금이라도 돌아오라. 눅 15:20 '아직도 거리가 먼데 아버지가 보고 불쌍히 여겨 달려가 목을 안고 입을 맞추니'"},
        {"상황":"자기 안의 죄를 발견하고 충격받은 분", "성경원리":"'불의가 드러났다(니므차)' - 숨겨져 있던 죄가 밖으로 나오는 것은 고통스럽지만 치유의 시작이다", "실제적용":"죄가 드러나는 것은 고통스럽지만 숨겨진 채로 자라는 것보다 낫다. 요일 1:9 '우리가 자백하면 그는 미쁘시고 의로우사 우리 죄를 사하시며'. 고백이 치유의 시작이다"}
