        {"구분":"공포의 대상이 됨", "내용":"선망에서 공포로 변한 존재", "그리스도연결":"그리스도는 공포가 아닌 소망의 대상 (골 1:27, 딤전 1:1)"},
        {"구분":"너를 아는 모든 자의 경악", "내용":"한때 알던 자들이 놀라고 두려워함", "그리스도연결":"그리스도를 아는 자들은 소망과 평안 속에 거한다 (빌 3:10, 요 17:3)"},
        {"구분":"세 번 반복되는 종결 공식", "내용":"26:21, 27:36, 28:19의 동일한 결론", "그리스도연결":"베드로에게 세 번 '네가 나를 사랑하느냐' 물으신 회복의 반복 (요 21:15-17)"}
