    표5_매튜헨리: [
        {"영어원문":"The word of the Lord came concerning Sidon, Tyre's neighbour and ally, showing that God's judgment extends to all confederates in sin.", "한국어번역":"여호와의 말씀이 두로의 이웃이자 동맹인 시돈에 관하여 임하였으니, 죄의 동맹자 모두에게 심판이 미침을 보여준다.", "핵심통찰":"악의 동맹자도 심판에서 면제되지 않는다"},
        {"영어원문":"After the lengthy prophecy against Tyre, this brief word against Sidon prepares for the promise of Israel's restoration.", "한국어번역":"두로에 대한 긴 예언 후, 시돈에 대한 이 짧은 말씀은 이스라엘의 회복 약속을 준비한다.", "핵심통찰":"심판의 끝에 회복의 약속이 기다린다"},
        {"영어원문":"God's word reaches every nation; none is too small or too remote for His notice.", "한국어번역":"하나님의 말씀은 모든 민족에게 미치니, 너무 작거나 너무 멀어서 주목받지 못하는 나라는 없다.", "핵심통찰":"어떤 민족도 하나님의 관심 밖에 있지 않다"}
    ],
    표6_설교자료: [
        {"대지":"제목", "내용":"시돈을 향한 말씀 - 동맹자의 심판과 회복의 서곡", "예화_적용":"하나님의 심판은 주요 대상만이 아니라 그 동맹까지 미친다"},
        {"대지":"서론", "내용":"두로에 대한 세 장의 긴 신탁이 끝나고, 이제 시돈에 대한 짧은 신탁이 시작된다. 시돈은 두로의 자매 도시이자 이스라엘에 바알 숭배를 전파한 이세벨의 고향이다. 하나님의 심판은 두로에서 그치지 않고 시돈까지 미친다", "예화_적용":"범죄 조직의 두목만이 아니라 조직원도 법의 심판을 받듯, 악의 동맹도 함께 심판받는다"},
        {"대지":"1대지: 여호와의 말씀이 임하다 (끊이지 않는 하나님의 관심)", "내용":"두로 신탁이 끝나자마자 시돈 신탁이 이어진다. 하나님의 관심은 한 민족에 머물지 않는다", "예화_적용":"좋은 의사가 한 환자만 보지 않듯, 하나님은 모든 민족을 돌보신다"},
        {"대지":"2대지: 시돈 - 두로의 동맹 (악의 공동 책임)", "내용":"시돈은 두로와 함께 이스라엘에 영적 해악을 끼쳤다. 악에 동조한 자도 공동 책임이 있다", "예화_적용":"방관자도 공범이 될 수 있듯, 악에 동조하는 것은 악에 참여하는 것이다"},
        {"대지":"3대지: 심판에서 회복으로 (시돈 신탁의 위치)", "내용":"시돈 신탁 직후(25-26절)에 이스라엘 회복 약속이 나온다. 열방 심판의 끝에 하나님 백성의 회복이 기다린다", "예화_적용":"긴 터널의 끝에 빛이 있듯, 심판의 끝에 회복의 약속이 있다"},
        {"대지":"결론", "내용":"하나님의 말씀은 두로를 넘어 시돈까지, 시돈을 넘어 이스라엘의 회복까지 이어진다. 심판은 목적이 아니라 회복을 위한 과정이다. 가장 어두운 심판의 밤 뒤에 가장 밝은 회복의 아침이 기다린다", "예화_적용":"시 30:5 '저녁에는 울음이 깃들일지라도 아침에는 기쁨이 오리로다'"}
    ],
