    표8_상담적용: [
        {"상황":"악한 환경에 동조하고 있는 분", "성경원리":"시돈은 두로의 동맹으로서 함께 심판받았다. 악에 동조하는 것도 심판의 대상이다", "실제적용":"악한 환경에서 벗어나라. 계 18:4 '내 백성아 거기서 나오라 그의 죄에 참여하지 말라'. 동조하지 않는 용기가 필요하다"},
        {"상황":"심판의 끝이 보이지 않아 절망하는 분", "성경원리":"시돈 신탁 직후에 이스라엘 회복 약속이 이어진다. 심판의 끝에 회복이 있다", "실제적용":"지금이 심판의 시간이라 해도 회복의 아침이 올 것이다. 시 30:5 '아침에는 기쁨이 오리로다'. 인내하라"},
        {"상황":"자기가 너무 작고 보잘것없다고 느끼는 분", "성경원리":"시돈이라는 작은 도시에도 하나님의 말씀이 임했다. 하나님의 관심 밖에 있는 존재는 없다", "실제적용":"하나님은 당신을 알고 계시고 관심을 가지고 계신다. 마 10:30 '너희에게는 머리털까지 다 세신 바 되었나니'. 당신은 하나님께 중요한 존재이다"}
    ],
