        {"구분":"얼굴을 돌려 예언함", "내용":"구체적 대상을 향한 예언적 행위", "그리스도연결":"예수님이 예루살렘을 향하여 얼굴을 돌이키심 (눅 9:51)"},
        {"구분":"이방에 대한 선지자의 사명", "내용":"이스라엘 너머 열방을 향한 사역", "그리스도연결":"이방의 빛이 되신 그리스도 (사 42:6, 눅 2:32)"}
