    표8_상담적용: [
        {"상황":"사방에서 어려움이 닥쳐 절망하는 분", "성경원리":"사방에서 칼이 임해도 하나님을 향한 길은 열려 있다. '나를 여호와인 줄 알리라'는 인식의 기회이다", "실제적용":"사방이 막혀도 위를 향한 길은 열려 있다. 시 121:1-2 '나의 도움이 어디서 올까 도움이 천지를 지으신 여호와에게서 오도다'"},
        {"상황":"전염병이나 재난 가운데 있는 분", "성경원리":"전염병도 하나님의 주권 아래 있다. 재난 속에서도 하나님을 알 수 있다", "실제적용":"재난이 하나님의 부재를 뜻하지 않는다. 재난 속에서 더 깊이 하나님을 만날 수 있다. 시 46:1 '환난 중에 만날 큰 도움'"},
        {"상황":"하나님의 심판이 무섭다고 느끼는 분", "성경원리":"심판의 목적이 파괴가 아니라 '나를 여호와인 줄 알게 하기 위함'이다", "실제적용":"심판하시는 하나님께로 도망가는 것이 유일한 안전이다. 히 4:16 '은혜의 보좌 앞에 담대히 나아가자'"}
    ],
