        {"대지":"3대지: 이집트 - 부러진 갈대 지팡이 (거짓 의지처)", "내용":"이집트는 이스라엘이 바벨론 대신 의지하려 한 강대국이다. 그러나 이집트도 심판받을 것이다. 인간적 동맹은 참된 안전이 아니다", "예화_적용":"사 36:6 '부러진 갈대 지팡이 곧 애굽을 의지하는도다 사람이 그것에 의지하면 손을 찌르리라'"},
        {"대지":"결론", "내용":"예루살렘이 포위된 절박한 순간에 하나님은 이스라엘이 의지하던 이집트의 심판을 예언하셨다. 이것은 인간적 구원자에 대한 기대를 무너뜨리고, 오직 하나님만이 참된 구원자이심을 선언하는 것이다. 위기 때 누구를 의지하는가? 이집트(세상의 힘)인가, 여호와인가?", "예화_적용":"시 20:7 '누구는 병거, 누구는 말을 의지하나 우리는 우리 하나님 여호와의 이름을 자랑하리로다'"}
