        {"교리":"왕과 나라의 동반 심판", "설명":"'바로와 온 이집트'가 함께 심판받는다. 지도자의 교만이 나라 전체에 영향을 미치기 때문이다. 지도자의 죄가 공동체 전체의 운명을 좌우하는 것이 성경적 원리이다", "관련구절":"삼하 24:15-17, 단 4:25, 잠 29:4, 호 4:9"},
        {"교리":"출애굽의 하나님과 이집트 심판", "설명":"출애굽 때 이집트를 심판하신 하나님이 다시 이집트를 심판하신다. 하나님의 역사적 행위는 일회적이 아니라 반복적이다. 이집트의 교만은 출애굽 시대와 동일하며, 심판도 동일하다", "관련구절":"출 7-12장, 사 19장, 렘 46장, 겔 30-32장"}
