        {"교리":"심판을 통한 인식", "설명":"'나를 여호와인 줄 알리라'가 이집트에도 적용된다. 이집트의 심판도 하나님을 알리기 위한 것이다. 출애굽 때처럼(출 14:18) 이집트가 하나님의 주권을 인정하게 되는 것이 심판의 목적이다", "관련구절":"출 7:5, 출 14:18, 겔 30:26, 겔 32:15"},
        {"교리":"갈대와 반석의 대비", "설명":"이집트가 부러지는 갈대라면, 하나님은 흔들리지 않는 반석이시다(신 32:4). 갈대를 의지하면 쓰러지지만, 반석을 의지하면 서게 된다. 의지의 대상이 인생의 결과를 결정한다", "관련구절":"신 32:4, 시 18:2, 마 7:24-27, 시 62:2"}
