    표5_매튜헨리: [
        {"영어원문":"When they took hold of thee thou didst break, and didst rend all their shoulder; a broken reed not only fails but wounds.", "한국어번역":"그들이 너를 잡을 때 네가 부러져 그 모든 어깨를 찢었으니, 부러진 갈대는 실패할 뿐 아니라 상처를 입힌다.", "핵심통찰":"거짓 의지처는 실패할 뿐 아니라 상처까지 입힌다"},
        {"영어원문":"When they leaned upon thee thou brakest, and madest all their loins to be at a stand—their very foundation was shaken.", "한국어번역":"그들이 너를 의지하매 네가 부러져 그 모든 허리를 떨리게 하였으니, 그들의 기반 자체가 흔들렸다.", "핵심통찰":"거짓 의지처에 기대면 기반 자체가 흔들린다"},
        {"영어원문":"This is what comes of trusting in creatures rather than in the Creator—disappointment, damage, and ruin.", "한국어번역":"이것이 창조주 대신 피조물을 의지한 결과이니 - 실망, 손해, 파멸이다.", "핵심통찰":"피조물 의지의 결과: 실망 → 손해 → 파멸"}
    ],
    표6_설교자료: [
        {"대지":"제목", "내용":"부러진 갈대가 어깨를 찢다 - 거짓 의지처의 역효과", "예화_적용":"세상의 도움은 도움이 안 될 뿐 아니라 상처를 입힌다"},
        {"대지":"서론", "내용":"갈대 지팡이를 잡았다. 튼튼해 보였다. 그런데 무게를 걸자 부러졌다. 부러진 갈대 조각이 손바닥을 관통했다. 어깨가 찢어졌다. 허리가 흔들렸다. 이것이 이집트를 의지한 이스라엘의 경험이다. 도움을 받으려다 오히려 상처를 입었다. 보호받으려다 오히려 기반이 흔들렸다", "예화_적용":"부실한 의자에 앉으면 넘어져 다치듯, 부실한 의지처에 기대면 넘어져 상처를 입는다"},
        {"대지":"1대지: 잡을 때 부러짐 (도움의 순간의 배신)", "내용":"이집트를 잡는 순간 부러졌다. 가장 필요한 순간에 실패하는 것이 세상 도움의 본질이다", "예화_적용":"비 올 때 우산이 부러지는 것처럼, 위기의 순간에 세상의 도움은 무너진다"},
        {"대지":"2대지: 어깨를 찢음 (도움이 해가 됨)", "내용":"부러진 갈대가 어깨를 찢었다. 도움이 되기는커녕 해가 되었다. 이집트 동맹이 바벨론의 분노만 키운 것이다", "예화_적용":"잘못된 투자가 원금까지 잃게 하듯, 잘못된 의지처는 기존의 것까지 잃게 만든다"},
        {"대지":"3대지: 허리를 떨리게 함 (기반의 흔들림)", "내용":"허리가 흔들린다는 것은 기반이 무너진다는 뜻이다. 이집트를 의지한 결과 이스라엘의 국가 기반이 흔들렸다", "예화_적용":"잘못된 파트너와의 사업이 회사 전체를 위기에 빠뜨리듯, 잘못된 의지처가 전체를 흔든다"},
        {"대지":"결론", "내용":"이집트라는 갈대 지팡이는 이스라엘의 어깨를 찢고 허리를 흔들었다. 그러나 하나님의 지팡이는 다르다. 시 23:4 '주의 지팡이와 막대기가 나를 안위하시나이다'. 부러지지 않는 지팡이, 찌르지 않는 지팡이, 안위하는 지팡이. 이것이 하나님의 지팡이이다", "예화_적용":"마 12:20 '상한 갈대를 꺾지 아니하며 꺼져가는 심지를 끄지 아니하시리라' - 부러진 갈대처럼 우리를 상하게 하는 것이 아니라 상한 갈대를 치유하시는 분이 그리스도이시다"}
    ],
