    표8_상담적용: [
        {"상황":"도움을 구했는데 오히려 상처받은 분", "성경원리":"이집트를 의지한 이스라엘이 오히려 어깨가 찢어지고 허리가 흔들렸다. 잘못된 의지처는 해를 끼친다", "실제적용":"상처의 고통을 하나님께 가져가라. 하나님은 상한 갈대를 꺾지 않으시는 분이다(마 12:20). 참된 치유는 하나님께 있다"},
        {"상황":"같은 실수를 반복하는 분", "성경원리":"이스라엘은 여러 번 이집트를 의지했다가 배신당하는 같은 실수를 반복했다", "실제적용":"반복되는 실수의 패턴을 인식하라. 잘못된 의지처를 바꾸지 않으면 결과도 바뀌지 않는다. 의지의 대상을 하나님으로 바꾸라"},
        {"상황":"기반이 흔들려 불안한 분", "성경원리":"허리(기반)가 흔들리는 것은 잘못된 의지처의 결과이다. 참된 기반은 하나님이시다", "실제적용":"시 125:1 '여호와를 의지하는 자는 시온 산이 요동하지 아니하고 영원히 있음 같도다'. 흔들리지 않는 기반 위에 서라"}
    ],
