        {"대지":"2대지: 나를 여호와인 줄 알리라 (심판 속의 계시)", "내용":"황무지가 되어도 목적이 있다 - 하나님을 아는 것이다. 가장 처참한 상황에서도 하나님은 자기를 알리신다", "예화_적용":"가장 어두운 밤에 별이 가장 밝게 빛나듯, 가장 극심한 심판 속에서 하나님의 존재가 가장 분명해진다"},
        {"대지":"3대지: 바로의 말이 증거가 됨 (자기 고백의 심판)", "내용":"3절의 '내 강은 내 것이라 내가 만들었다'가 9절에서 심판의 이유로 다시 인용된다. 자기 입의 말이 자기를 심판한다", "예화_적용":"마 12:37 '네 말로 정죄함을 받으리라'. 입에서 나오는 교만한 말을 경계하라"},
        {"대지":"결론", "내용":"이집트가 황무지가 된 이유는 명확하다. '내 것이라 내가 만들었다'는 교만. 이 한마디가 풍요로운 땅을 황무지로 만들었다. 우리의 입에서도 같은 교만이 나오고 있지 않은가? '내가 이루었다', '내 힘으로 했다.' 이 말들을 '하나님의 은혜로 되었다'(고전 15:10)로 바꾸는 것이 축복의 시작이다", "예화_적용":"고전 15:10 '그러나 나의 나 된 것은 하나님의 은혜로 된 것이니'"}
