        {"상황":"과거에 비해 현재가 초라한 분", "성경원리":"이집트가 제국에서 약소국이 된 것이 하나님의 계획이었다. 초라함이 하나님의 뜻일 수 있다", "실제적용":"현재의 초라함을 겸손의 훈련으로 받으라. 슥 4:10 '작은 일의 날을 멸시하지 말라'. 작은 것에 충실한 것이 하나님의 뜻"},
        {"상황":"하나님이 왜 축복을 줄이시는지 이해 못하는 분", "성경원리":"하나님이 이집트를 줄이신 것은 교만을 치유하고 이스라엘이 이집트를 의지하지 않게 하기 위함이었다", "실제적용":"하나님이 무언가를 줄이시는 데에는 이유가 있다. 이해되지 않아도 하나님의 지혜를 신뢰하라. 롬 11:33 '하나님의 지혜와 지식의 부요함이여'"}
