        {"대지":"2대지: 수고의 삯 (정당한 보상)", "내용":"13년의 수고에 대한 보상이 이집트의 부이다. 하나님은 수고한 자에게 정당한 보상을 주시는 분이다", "예화_적용":"딤전 5:18 '일꾼이 그 삯을 받는 것이 마땅하다'. 하나님은 정당한 보상의 하나님이시다"},
        {"대지":"3대지: 재물, 물품, 재산의 약탈 (세상 부의 일시성)", "내용":"이집트의 수천 년 부가 한 번의 전쟁으로 탈취된다. 세상의 부는 일시적이다", "예화_적용":"마 6:19 '보물을 땅에 쌓지 말라 거기는 좀과 녹이 해하며 도적이 구멍을 뚫고 도적질하느니라'"},
        {"대지":"결론", "내용":"하나님은 수고에 대해 보상하시는 분이다. 두로에서 못 받은 것을 이집트에서 주신다. 우리의 수고도 마찬가지이다. 당장 여기서 보상받지 못해도, 하나님은 다른 곳에서, 다른 방식으로, 때로는 더 크게 보상하신다. 고전 15:58 '너희 수고가 주 안에서 헛되지 않는다'", "예화_적용":"계 22:12 '보라 내가 속히 오리니 내가 줄 상이 내게 있어 각 사람에게 그가 행한 대로 갚아 주리라'"}
