        {"상황":"역사 속에서 하나님의 계획을 찾으려는 분", "성경원리":"느부갓네살의 전쟁도 하나님의 계획 안에 있었다. 역사의 모든 사건 뒤에 하나님이 계시다", "실제적용":"당장 이해되지 않는 역사적 사건도 하나님의 주권 안에 있다. 단 2:21 '왕들을 폐하시며 세우시며'. 역사를 주관하시는 하나님을 신뢰하라"}
