    표5_매튜헨리: [
        {"영어원문":"In that day will I cause the horn of Israel to bud forth—out of their low estate God will raise them again.", "한국어번역":"그 날에 내가 이스라엘에게 뿔이 나게 하리라 - 그들의 낮은 상태에서 하나님이 다시 일으키실 것이다.", "핵심통찰":"가장 낮은 상태에서 하나님이 뿔(힘)을 주신다"},
        {"영어원문":"I will give thee the opening of the mouth—Ezekiel shall speak freely the words of comfort and restoration.", "한국어번역":"내가 너에게 입을 열게 하리라 - 에스겔이 위로와 회복의 말씀을 자유롭게 전할 것이다.", "핵심통찰":"심판의 침묵이 끝나고 회복의 선포가 시작된다"},
        {"영어원문":"This is the bright ending to a dark chapter—from Egypt's ruin springs Israel's hope.", "한국어번역":"이것이 어두운 장의 밝은 결말이다 - 이집트의 멸망에서 이스라엘의 소망이 싹튼다.", "핵심통찰":"이집트의 멸망에서 이스라엘의 소망이 싹튼다"}
    ],
    표6_설교자료: [
        {"대지":"제목", "내용":"뿔이 나게 하리라 - 심판의 끝, 회복의 시작", "예화_적용":"가장 어두운 밤의 끝에 가장 밝은 새벽이 온다"},
        {"대지":"서론", "내용":"에스겔 29장의 마지막 절이자, 이집트 신탁 전체의 결론이다. 어두운 심판의 장들을 지나 마침내 희망의 빛이 비친다. '이스라엘에게 뿔이 나게 하리라.' 포로 상태의 이스라엘에게 힘과 존엄이 회복될 것이다. 그리고 에스겔의 입이 열려 회복의 메시지를 선포할 것이다", "예화_적용":"겨울 땅에서 새싹이 돋아나듯, 심판의 땅에서 회복의 싹이 나온다"},
        {"대지":"1대지: 이스라엘에게 뿔이 남 (구원의 뿔)", "내용":"뿔은 힘, 존엄, 구원의 상징이다. 누가복음 1:69에서 '구원의 뿔'은 예수 그리스도를 가리킨다. 이스라엘의 궁극적 회복은 메시아 안에서 이루어진다", "예화_적용":"넘어진 나무에서 새 싹이 나듯(사 11:1), 포로의 이스라엘에서 구원의 뿔이 나온다"},
        {"대지":"2대지: 입을 열게 함 (선포의 회복)", "내용":"에스겔의 입이 열린다. 침묵의 시대가 끝나고 선포의 시대가 시작된다. 심판의 메시지에서 회복의 메시지로 전환", "예화_적용":"스가랴가 말을 못하다가 아기가 태어나자 입이 열린 것처럼(눅 1:64), 하나님의 때가 되면 침묵이 끝난다"},
        {"대지":"3대지: 나를 여호와인 줄 알리라 (궁극적 목적)", "내용":"29장의 마지막 말씀이자 모든 심판과 회복의 궁극적 목적. 하나님을 아는 것이 전부이다", "예화_적용":"요 17:3 '영생은 유일하신 참 하나님과 그가 보내신 자 예수 그리스도를 아는 것이니이다'"},
        {"대지":"결론", "내용":"에스겔 29장이 끝난다. 이집트의 심판으로 시작하여 이스라엘의 뿔로 끝난다. 심판의 장이 소망의 절로 마무리된다. 하나님의 이야기는 항상 이렇게 끝난다. 가장 어두운 장의 마지막 절에 가장 밝은 희망이 있다. 우리의 이야기도 그러하기를 바란다. 구원의 뿔이신 그리스도를 바라보자", "예화_적용":"눅 1:68-69 '찬송하리로다 주 이스라엘의 하나님이여 그 백성을 돌보사 속량하시며 우리를 위하여 구원의 뿔을 그 종 다윗의 집에 일으키셨으니'"}
    ],
