    표5_매튜헨리: [
        {"영어원문":"Howl ye, Woe worth the day! This is the language of the prophets when they see the Day of the Lord approaching.", "한국어번역":"슬피 울라, 슬프다 그 날이여! 이것은 선지자들이 여호와의 날이 다가옴을 볼 때의 언어이다.", "핵심통찰":"'여호와의 날'이 다가올 때 선지자는 통곡한다"},
        {"영어원문":"The Day of the Lord is a day of reckoning for all the proud and all the wicked; none shall escape it.", "한국어번역":"여호와의 날은 모든 교만한 자와 악인에게 결산의 날이니, 아무도 피하지 못할 것이다.", "핵심통찰":"여호와의 날은 피할 수 없는 결산의 날"}
    ],
    표6_설교자료: [
        {"대지":"제목", "내용":"슬프다 그 날이여 - 여호와의 날이 가까왔다", "예화_적용":"모든 교만과 불의가 심판받는 날이 온다"},
        {"대지":"서론", "내용":"에스겔이 외친다. '슬프다 그 날이여!' 어떤 날인가? 다음 절에서 밝혀진다. '여호와의 날이 가까왔다.' 이집트에 대한 심판이 '여호와의 날'이라는 종말론적 프레임 안에 놓인다. 역사적 사건이면서 동시에 최후 심판의 예표. 그 날이 오고 있다", "예화_적용":"지진 경보가 울리면 미리 대피하듯, '여호와의 날'의 경고를 듣고 준비해야 한다"},
        {"대지":"1대지: 슬피 울라 (통곡의 명령)", "내용":"'헤일리루(슬피 울라)'는 장례식의 통곡이다. 이집트의 죽음을 미리 애도하라는 명령", "예화_적용":"예수님도 예루살렘을 위해 우셨다(눅 19:41). 심판 앞에서의 통곡은 냉정함이 아닌 연민의 표현"},
        {"대지":"2대지: 슬프다 그 날이여 (여호와의 날의 두려움)", "내용":"'여호와의 날'은 악인에게는 두려움의 날이다. 모든 교만과 불의가 심판받는 날", "예화_적용":"암 5:18 '여호와의 날을 사모하는 자에게 화 있을진저 그것은 어둠이요 빛이 아니다'. 준비 없이 그 날을 맞이하면 재앙이다"},
        {"대지":"3대지: 역사적 심판과 종말적 심판 (이중의 프레임)", "내용":"이집트에 대한 역사적 심판이 '여호와의 날'이라는 종말론적 프레임 안에 놓인다. 역사가 종말을 예고한다", "예화_적용":"살전 5:2 '주의 날이 도적같이 오리라'. 그 날을 준비하며 사는 것이 지혜이다"},
        {"대지":"결론", "내용":"'슬프다 그 날이여!' 이집트에 대한 이 외침은 모든 시대의 교만한 자들에게 향하는 경고이다. '여호와의 날'은 반드시 온다. 그러나 그리스도 안에 있는 자에게 그 날은 두려움이 아닌 구원의 날이다. 살전 5:9 '하나님이 우리를 세우심은 구원을 받게 하심이라'. 그 날을 소망으로 기다리자", "예화_적용":"딛 2:13 '복스러운 소망과 우리의 크신 하나님 구주 예수 그리스도의 영광이 나타나심을 기다리게 하셨으니'"}
    ],
