        {"대지":"2대지: 구름의 날 (어둠과 심판)", "내용":"구름은 하나님의 임재이면서 심판의 어둠이다. 의인에게는 보호의 구름이고 악인에게는 심판의 구름이다", "예화_적용":"같은 비가 씨앗에게는 생명이고 홍수 지역에게는 재앙이듯, 하나님의 임재는 마음 상태에 따라 다르게 경험된다"},
        {"대지":"3대지: 열방의 때 (보편적 심판)", "내용":"이집트만이 아닌 모든 민족의 심판. 하나님의 심판에 예외인 민족은 없다", "예화_적용":"행 17:31 '이는 정하신 사람으로 하여금 천하를 공의로 심판할 날을 작정하셨음이니'. 모든 민족이 심판대 앞에 선다"},
        {"대지":"결론", "내용":"여호와의 날이 가까왔다. 구름의 날, 열방의 때. 이것은 두려운 선언이지만, 그리스도 안에서는 소망의 선언이다. 계 1:7 '그가 구름을 타고 오시리라 각 사람의 눈이 그를 보겠고'. 같은 구름이지만, 그리스도를 아는 자에게는 구원의 구름이다. 그 날을 소망으로 기다리자", "예화_적용":"계 22:20 '이것들을 증언하신 이가 이르시되 내가 진실로 속히 오리라 하시거늘 아멘 주 예수여 오시옵소서'"}
