        {"대지":"3대지: 기초가 헐림 (근본의 파괴)", "내용":"이집트의 기초가 허물어진다. 수천 년 문명의 기반이 무너지는 것이다. 하나님 없는 기초는 결국 무너진다", "예화_적용":"시 11:3 '기초가 무너지면 의인이 무엇을 하랴'. 참된 기초는 하나님뿐이시다 (고전 3:11)"},
        {"대지":"결론", "내용":"칼, 죽임, 약탈, 기초 파괴 - 총체적 심판이 이집트에 임한다. 그러나 참된 기초이신 그리스도 위에 세운 것은 무너지지 않는다. 마 7:24-25 '반석 위에 지은 집은 비가 내리고 창수가 나고 바람이 불어 그 집에 부딪치되 무너지지 아니하나니'. 참된 기초 위에 삶을 세우자", "예화_적용":"고전 3:11 '이미 놓인 터 외에 능히 다른 터를 놓을 자가 없으니 이 터는 곧 예수 그리스도라'"}
