        {"교리":"악의 동맹에 대한 공동 심판", "설명":"이집트와 동맹한 모든 나라가 함께 심판받는다. 악에 동참하면 심판도 동참한다. 이것은 '악과의 동맹에서 벗어나라'는 경고이다", "관련구절":"고후 6:14, 계 18:4, 시 1:1, 잠 1:10-15"},
        {"교리":"이집트 피신 유다인의 심판 가능성", "설명":"'동맹한 땅의 백성'이 이집트로 피신한 유다인을 가리킨다면, 이것은 하나님의 뜻에 반하여 이집트에 간 자들에 대한 경고이다(렘 42-44장). 하나님의 뜻에 불순종하여 세상에 피신하면 세상의 심판에 동참하게 된다", "관련구절":"렘 42:15-17, 렘 44:12-14, 렘 43:10-13, 사 30:1-3"}
