        {"교리":"돕는 자의 무용함", "설명":"이집트를 '돕는 자들(오즈림)'이 모두 멸망한다. 인간적 도움은 하나님의 심판을 막지 못한다. 참된 도움은 오직 하나님으로부터 온다(시 121:1-2)", "관련구절":"시 121:1-2, 시 146:3-5, 사 31:1-3, 렘 17:5"},
        {"교리":"심판 속의 계시", "설명":"불의 심판 가운데서도 '나를 여호와인 줄 알리라'가 목적이다. 가장 극렬한 심판 속에서도 하나님은 자기를 알리시기를 원하신다. 심판은 파괴가 아닌 계시가 목적이다", "관련구절":"겔 28:22-23, 출 7:5, 겔 36:23, 시 9:16"}
