        {"상황":"역사의 큰 흐름에 불안한 분", "성경원리":"느부갓네살이라는 거대한 역사적 움직임도 하나님의 손 안에 있었다. 역사를 주관하시는 분은 하나님이시다", "실제적용":"시대의 큰 변화 속에서도 하나님이 역사를 주관하신다. 단 2:21 '때와 기한을 변하시며'. 하나님의 주권을 신뢰하라"}
