        {"대지":"서론", "내용":"심판이 더 구체화된다. 바벨론 군대가 '이끌려 온다(무바임)'. 호팔형(수동 사역형)이 핵심이다. 자기들이 원해서 온 것이 아니라 하나님에 의해 '이끌려 온' 것이다. 칼을 뽑아 이집트를 치고, 전사자가 땅에 가득해진다. 교만의 결과가 이토록 처참하다", "예화_적용":"체스의 말들이 선수의 손에 의해 움직이듯, 역사의 군대도 하나님의 손에 의해 이동한다"},
        {"대지":"1대지: 열방의 무서운 자들이 이끌려 옴 (하나님의 인도)", "내용":"바벨론 군대가 하나님에 의해 '이끌려 왔다'. 자기 의지가 아닌 하나님의 뜻에 의해 움직인 것", "예화_적용":"잠 21:1 '왕의 마음이 여호와의 손에 있음이 마치 봇도랑의 물 같아서 그가 임의로 인도하시느니라'"},
        {"대지":"2대지: 칼을 뽑아 이집트를 침 (구체적 심판)", "내용":"심판이 추상적이 아니라 구체적이다. 칼이 뽑히고 전쟁이 시작된다", "예화_적용":"하나님의 심판은 관념이 아닌 현실이다. 역사 속 전쟁과 멸망이 그 증거이다"},
        {"대지":"3대지: 전사자가 땅에 가득함 (교만의 참상)", "내용":"풍요의 땅이 시체로 뒤덮인다. 교만의 결과가 이토록 처참하다", "예화_적용":"전쟁 사진을 보면 교만의 결과가 얼마나 끔찍한지 알 수 있다. 교만은 자기뿐 아니라 수많은 사람을 죽인다"},
        {"대지":"결론", "내용":"바벨론 군대가 하나님에 의해 이끌려 왔다. 인간은 자기 의지로 역사를 만든다고 생각하지만, 실제로는 하나님의 큰 손이 역사를 이끌고 계시다. 이 진실이 우리에게 두 가지를 준다. 하나님 없이 사는 자에게는 두려움을, 하나님과 함께 사는 자에게는 안심을", "예화_적용":"롬 8:31 '하나님이 우리를 위하시면 누가 우리를 대적하리요'"}
