        {"영어원문":"I the Lord have spoken it—this seals every word with divine authority; what God says, God does.", "한국어번역":"나 여호와가 말하였느니라 - 이것이 모든 말씀을 신적 권위로 봉인한다. 하나님이 말씀하신 것을 하나님이 행하신다.", "핵심통찰":"하나님이 말씀하신 것은 반드시 행하신다"}
