    표6_설교자료: [
        {"대지":"제목", "내용":"나일강이 마르는 날 - 자랑의 종말", "예화_적용":"'내 것이라' 자랑한 것이 마르고 빼앗기는 것이 심판이다"},
        {"대지":"서론", "내용":"이집트에 대한 심판이 절정에 이른다. '내가 강들을 말리겠다.' 나일강, 이집트의 생명줄, 파라오가 '내 것이라 내가 만들었다'(29:3)고 자랑한 그 강이 마른다. 그리고 이집트 땅이 '악한 자의 손에 팔린다.' 하나님이 자기 이름을 걸고 선언하신다. '나 여호와가 말하였다'", "예화_적용":"석유가 고갈되면 산유국이 무너지듯, 나일강이 마르면 이집트가 무너진다. 자연 자원에 대한 교만은 그 자원의 제거로 심판받는다"},
        {"대지":"1대지: 강들을 말리다 (생명줄의 차단)", "내용":"나일강이 마른다. 이집트의 농업, 경제, 문명의 기초가 사라진다. 자랑한 것이 빼앗기는 하나님의 심판", "예화_적용":"신 8:18 '재물 얻을 능력을 주시는 이는 하나님이시다'. 자연의 풍요도 하나님의 선물이며, 하나님이 거두시면 사라진다"},
        {"대지":"2대지: 악한 자의 손에 팔림 (보호의 철회)", "내용":"하나님이 이집트를 '파신다'. 보호를 거두시면 적의 손에 넘겨진다. 보호의 철회 자체가 심판이다", "예화_적용":"부모가 아이를 보호하다가 손을 놓으면 아이가 위험에 처하듯, 하나님의 보호가 철회되면 심판이 된다"},
        {"대지":"3대지: 나 여호와가 말하였다 (절대적 보증)", "내용":"하나님이 자기 이름을 걸고 선언하신다. 이보다 더 확실한 보증은 없다", "예화_적용":"수 21:45 '여호와께서 이스라엘에게 말씀하신 선한 일이 하나도 남음이 없이 다 이루어졌더라'. 하나님의 말씀은 100% 성취된다"},
        {"대지":"결론", "내용":"나일강이 마르고, 땅이 팔리고, 하나님이 말씀하셨다. 이 세 가지가 이집트의 운명을 봉인한다. 그러나 우리에게는 다른 강이 있다. 마르지 않는 강, 생명수의 강. 요 7:38 '나를 믿는 자는 그 배에서 생수의 강이 흘러나오리라'. 세상의 강은 마르지만 그리스도의 생명수는 영원하다", "예화_적용":"계 22:1 '수정같이 맑은 생명수의 강이 하나님과 어린 양의 보좌로부터 나와서'"}
    ],
