        {"대지":"2대지: 노가 함락됨 (난공불락의 무너짐)", "내용":"테베의 견고한 성벽이 뚫린다. 인간이 만든 가장 견고한 것도 하나님 앞에서 무력하다", "예화_적용":"여리고 성이 나팔 소리에 무너졌듯(수 6장), 하나님의 심판 앞에 무너지지 않을 성벽은 없다"},
        {"대지":"3대지: 놉에 대낮의 적 (피할 수 없는 심판)", "내용":"적이 대낮에 당당히 온다. 숨을 곳도 시간도 없다. 심판은 피할 수 없다", "예화_적용":"살전 5:3 '평안하다 할 때 갑자기 멸망이 이르리니'. 대비하지 않으면 심판은 갑자기 온다"},
        {"대지":"결론", "내용":"불, 산고, 함락, 대낮의 적. 심판의 형태는 다양하지만 피할 수 없다는 것은 동일하다. 그러나 그리스도 안에서는 심판이 아닌 구원이 있다. 롬 8:1 '그리스도 예수 안에 있는 자에게는 결코 정죄함이 없나니'. 지금 그리스도 안으로 피하자", "예화_적용":"시 91:1 '지극히 높으신 이의 은밀한 곳에 거주하는 자는 전능하신 이의 그늘 아래에 살리로다'"}
