        {"대지":"서론", "내용":"두 우상의 도시가 심판받는다. 아웬(온/헬리오폴리스) - 태양신의 도시. 하나님은 이 도시를 '아웬(허무)'이라 부르신다. 비베셋(부바스티스) - 고양이 여신의 도시. 70만 명이 모이는 축제의 도시. 이 두 도시의 청년들이 칼에 쓰러지고, 주민은 포로로 끌려간다. 우상의 도시의 비극적 종말이다", "예화_적용":"인스타그램에서 수백만 '좋아요'를 받아도 하나님 앞에서는 '아웬(허무)'일 수 있다"},
        {"대지":"1대지: 아웬 - 온의 다른 이름 (하나님의 평가)", "내용":"태양신의 도시 '온'을 하나님이 '아웬(허무)'이라 부르신다. 세상의 영광에 대한 하나님의 충격적 평가", "예화_적용":"전 1:2 '헛되고 헛되며 헛되고 헛되니 모든 것이 헛되도다'. 하나님 없는 세상의 영광은 허무이다"},
        {"대지":"2대지: 청년들이 칼에 쓰러짐 (미래의 상실)", "내용":"도시의 청년(미래 세대)이 죽는다. 현재의 교만이 다음 세대의 생존까지 위협한다", "예화_적용":"전쟁에서 젊은이들이 희생되는 것이 가장 큰 비극이듯, 교만의 대가를 다음 세대가 치른다"},
        {"대지":"3대지: 포로로 끌려감 (자유의 상실)", "내용":"살아남은 자들은 포로가 된다. 이집트가 이스라엘을 종으로 삼았던 것의 보응", "예화_적용":"갈 6:7 '사람이 무엇으로 심든지 그대로 거두리라'. 남을 종으로 삼았던 자가 자기도 종이 된다"},
        {"대지":"결론", "내용":"세상이 '온(영광)'이라 부르는 것을 하나님은 '아웬(허무)'이라 부르신다. 이 평가의 차이가 인생의 방향을 결정한다. 세상의 기준으로 살 것인가, 하나님의 기준으로 살 것인가? 허무한 것에 인생을 거는 대신, 영원한 것에 투자하자", "예화_적용":"마 6:19-20 '보물을 땅에 쌓지 말고 하늘에 쌓으라'"}
