        {"상황":"자녀 세대의 미래가 걱정되는 분", "성경원리":"청년들이 칼에 쓰러졌다. 현재의 교만이 다음 세대에 영향을 미친다", "실제적용":"다음 세대를 위해 기도하고 믿음의 본을 보이라. 잠 22:6 '마땅히 행할 길을 아이에게 가르치라'. 우리의 신앙이 자녀의 미래를 결정한다"},
        {"상황":"자유를 잃고 속박 속에 있는 분", "성경원리":"포로로 끌려간 이집트인들처럼 자유를 잃을 수 있다. 그러나 그리스도는 자유를 주신다", "실제적용":"요 8:36 '아들이 너희를 자유롭게 하면 참으로 자유로운 자가 되리라'. 그리스도 안에서 참 자유를 얻으라"}
