        {"영어원문":"The yokes of Egypt shall be broken—she who put yokes on others shall have her own broken.", "한국어번역":"이집트의 멍에가 꺾이리니 - 다른 이에게 멍에를 씌운 자가 자기 멍에가 꺾인다.", "핵심통찰":"억압한 자가 억압당하는 보응"}
