        {"교리":"30:1-19의 신학적 총괄", "설명":"이 단락은 여호와의 날(2-3절) → 칼의 심판(4-5절) → 동맹의 몰락(5-6절) → 황무(7절) → 불(8절) → 구스의 공포(9절) → 바벨론의 도구(10-11절) → 강의 마름(12절) → 도시별 심판(13-18절) → 하나님 인식(19절)으로 구성된다. 종말론적 선포에서 시작하여 구체적 역사적 심판을 거쳐 하나님 인식으로 마무리되는 완전한 구조", "관련구절":"겔 30:2-3, 겔 30:10, 겔 30:13-18, 겔 30:19"}
