        {"대지":"2대지: 나를 여호와인 줄 알리라 (궁극적 목적)", "내용":"에스겔서에서 70회 이상 반복되는 핵심 공식. 모든 역사의 궁극적 목적은 하나님을 아는 것이다", "예화_적용":"요 17:3 '영생은 유일하신 참 하나님과 그가 보내신 자 예수 그리스도를 아는 것이니이다'. 하나님을 아는 것이 모든 것의 목적이요 영생의 본질"},
        {"대지":"3대지: 30:1-19의 총괄 (여호와의 날에서 여호와 인식으로)", "내용":"'여호와의 날'(2-3절)로 시작하여 '나를 여호와인 줄 알리라'(19절)로 끝나는 완전한 구조. 시작과 끝이 모두 여호와이시다", "예화_적용":"계 1:8 '나는 알파와 오메가라 처음과 나중이라'. 모든 것의 시작과 끝이 하나님이시다"},
        {"대지":"결론", "내용":"'나를 여호와인 줄 알리라.' 이 한마디가 모든 것을 요약한다. 이집트에 대한 심판도, 우리 삶의 고난도, 역사의 모든 사건도 궁극적으로 하나님을 아는 것을 위한 것이다. 오늘 우리는 하나님을 얼마나 알고 있는가? 지식으로만 아는가, 인격적으로 아는가? 렘 9:24 '자랑하는 자는 이것으로 자랑할지니 곧 명철하여 나를 아는 것이라'", "예화_적용":"렘 9:24 '나를 아는 것과 나 여호와가 세상에서 인자와 정의와 공의를 행하는 자인 줄 아는 것이라 나는 이 일을 기뻐하노라'"}
