        {"대지":"서론", "내용":"BC 587년 4월, 이집트 파라오 호프라가 예루살렘을 돕기 위해 군대를 보냈다가 바벨론에 패하고 퇴각했다. 이스라엘의 마지막 희망이 무너진 것이다. 바로 그 시점에 하나님의 말씀이 에스겔에게 임한다. 세상의 희망이 무너질 때 하나님이 말씀하신다", "예화_적용":"가장 절망적인 순간이 하나님의 음성을 가장 명확하게 듣는 순간일 수 있다"},
        {"대지":"결론", "내용":"마지막 희망이 꺾인 날, 하나님은 침묵하지 않으셨다. 세상의 희망이 무너질 때 하나님의 말씀이 임한다. 절망의 순간이 하나님을 만나는 순간이 될 수 있다", "예화_적용":"시 46:1 '하나님은 우리의 피난처요 힘이시니 환난 중에 만날 큰 도움이시라'"}
